//###########################################################
onMessage = function(evnt) {
  var i, len, listener, parts, price, ref;
  parts = evnt.data.split(" ");
  switch (parts[0]) {
    case "liveDataUpdate":
      if (symToListeners[parts[1]] != null) {
        price = parseFloat(parts[2]);
        if (isNaN(price)) {
          return log(`price for ${parts[1]} is NaN!`);
        }
        ref = symToListeners[parts[1]];
        for (i = 0, len = ref.length; i < len; i++) {
          listener = ref[i];
          listener(parts[1], price);
        }
      } else {
        log(`no listener for Symbol: ${parts[1]}`);
      }
      break;
    case "subscribe":
      if (parts[1] === "success") {
        log(`subscribed to ${parts[2]}`);
      } else if (parts[1] === "error") {
        log(`subscription error: ${parts[2]}`);
      }
  }
};

